import{_ as s,C as i,o as l,c,j as o,a as n,E as r,a2 as a}from"./chunks/framework.BSaF8iZ6.js";const k=JSON.parse('{"title":"Manage Inventory","description":"","frontmatter":{},"headers":[],"relativePath":"inventory/manage-inventory.md","filePath":"inventory/manage-inventory.md","lastUpdated":1789411447000}'),g={name:"inventory/manage-inventory.md"};function d(h,t,u,p,v,y){const e=i("ImagePopup");return l(),c("div",null,[t[0]||(t[0]=o("h1",{id:"manage-inventory",tabindex:"-1"},[n("Manage Inventory "),o("a",{class:"header-anchor",href:"#manage-inventory","aria-label":'Permalink to "Manage Inventory"'},"​")],-1)),t[1]||(t[1]=o("div",{class:"page-roles"},[o("span",{class:"role role--seller"},"Seller")],-1)),t[2]||(t[2]=o("p",null,"Manage Inventory lets you update the stock of all your products on one screen, for each of your inventory sources, and save every change at once.",-1)),t[3]||(t[3]=o("p",null,[n("Go to "),o("strong",null,"Inventories >> Manage Inventory"),n(".")],-1)),r(e,{src:"/images/manage-inventory/manage.png",alt:"The Manage Inventory screen"}),t[4]||(t[4]=a('<h2 id="what-the-screen-shows" tabindex="-1">What the screen shows <a class="header-anchor" href="#what-the-screen-shows" aria-label="Permalink to &quot;What the screen shows&quot;">​</a></h2><p>The list includes your simple and virtual products, and each variant of a product with variations as its own row. It covers the products you created and the catalog products you sell as your own.</p><p>Each row shows:</p><ul><li>the image, name, SKU, type and ID, and for a variant a <strong>Parent</strong> link to the main product;</li><li>the category and the price, with an <strong>Edit price</strong> link that opens <a href="./../pricing/manage-pricing">Manage Pricing</a> for that product;</li><li>the <strong>Listing Status</strong>: <strong>Active</strong> when the product is on and approved, <strong>Unapproved</strong> when it is on but not yet approved, and <strong>Inactive</strong> when it is switched off;</li><li>how many were <strong>Sold</strong>, how many are <strong>Undelivered</strong> and how many were <strong>Canceled</strong>;</li><li>the total <strong>Stock</strong>, or <strong>Stock Not Managed</strong> when the product doesn&#39;t track stock.</li></ul><h2 id="update-the-stock-of-a-product" tabindex="-1">Update the stock of a product <a class="header-anchor" href="#update-the-stock-of-a-product" aria-label="Permalink to &quot;Update the stock of a product&quot;">​</a></h2><ol><li>Go to <strong>Inventories &gt;&gt; Manage Inventory</strong>.</li><li>Click the arrow at the start of the product&#39;s row.</li><li>Under <strong>Inventories</strong>, change the quantity for each source. Type a number or use the <strong>−</strong> and <strong>+</strong> buttons.</li><li>Click <strong>Save Inventories</strong> in the bar at the bottom of the page.</li></ol>',6)),r(e,{src:"/images/manage-inventory/edit-stock.png",alt:"A product row opened to change stock in each inventory source"}),t[5]||(t[5]=a('<p>Changed quantities are highlighted, and the bar counts how many products you changed. Click <strong>Discard</strong> to undo them all. Your changes stay while you move between pages or search, but they are lost if you reload the page before saving.</p><p>You&#39;ll see <strong>Inventories saved successfully.</strong></p><h2 id="update-the-stock-of-many-products" tabindex="-1">Update the stock of many products <a class="header-anchor" href="#update-the-stock-of-many-products" aria-label="Permalink to &quot;Update the stock of many products&quot;">​</a></h2><ol><li>Tick the products.</li><li>In <strong>Inventory Source</strong>, choose <strong>All Sources</strong> or one source.</li><li>In <strong>Action</strong>, choose <strong>Set to</strong>, <strong>Increase by</strong> or <strong>Decrease by</strong>.</li><li>Enter the <strong>Value</strong>.</li><li>Click <strong>Apply</strong>.</li><li>Click <strong>Save Inventories</strong>.</li></ol>',4)),r(e,{src:"/images/manage-inventory/bulk-stock.png",alt:"Changing the stock of several products at once"}),t[6]||(t[6]=a('<p><strong>Apply</strong> changes only the ticked products on the current page, and stock never goes below 0. Nothing is saved until you click <strong>Save Inventories</strong>.</p><h2 id="switch-products-on-or-off" tabindex="-1">Switch products on or off <a class="header-anchor" href="#switch-products-on-or-off" aria-label="Permalink to &quot;Switch products on or off&quot;">​</a></h2><ol><li>Tick the products.</li><li>Click <strong>Select Action</strong>, point to <strong>Update Status</strong> and click <strong>Active</strong> or <strong>Inactive</strong>.</li></ol><p>You&#39;ll see <strong>Product status updated successfully.</strong></p><h2 id="find-products" tabindex="-1">Find products <a class="header-anchor" href="#find-products" aria-label="Permalink to &quot;Find products&quot;">​</a></h2><p>Search by product name or SKU, or click <strong>Filter</strong> to narrow the list by <strong>Listing Status</strong>, <strong>Product</strong>, <strong>SKU</strong>, <strong>Category</strong>, <strong>Type</strong> or <strong>ID</strong>.</p><h2 id="low-stock" tabindex="-1">Low stock <a class="header-anchor" href="#low-stock" aria-label="Permalink to &quot;Low stock&quot;">​</a></h2><p>Products at or below the store&#39;s low-stock level are listed under <strong>Products low on stock</strong> on your <a href="./../seller-panel/dashboard">Dashboard</a>.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>A product that doesn&#39;t manage stock is always available, whatever the quantity.</li><li>Every inventory source you have appears here, including inactive ones. Stock in an inactive source isn&#39;t available to customers.</li><li>Team members need <strong>Manage Inventory</strong>, with <strong>Save Inventories</strong> to save and <strong>Update Status</strong> to switch products on or off.</li></ul>',10))])}const f=s(g,[["render",d]]);export{k as __pageData,f as default};
